package hu.synostream.android;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class NasProfileTest {
 TorrentRulesTest.Memory legacy(){TorrentRulesTest.Memory m=new TorrentRulesTest.Memory();m.put("address","fixture-qc");m.put("local","http://192.0.2.10:5000");m.put("user","Alice");m.put("libraries_owner","fixture-qc|alice");m.put("edits:fixture-qc|alice","{\"manual\":{\"movie:/a\":{\"id\":1}}}");return m;}
 NasClient.Credentials changed(){return new NasClient.Credentials("https://nas.example.org:5001","http://192.0.2.10:5000","","fixture-qc","Alice","secret","123456");}
 @Test public void legacyAnchorSurvivesAddressChanges()throws Exception{NasProfile p=NasProfile.load(legacy());assertEquals("fixture-qc|alice",p.routes(changed()).owner(" ALICE "));}
 @Test public void profileRoundTripRetainsIdAndOwner()throws Exception{NasProfile p=NasProfile.load(legacy()).routes(changed());NasProfile again=NasProfile.from(p.json("Alice"));assertEquals(p.id,again.id);assertEquals(p.owner("alice"),again.owner("alice"));assertEquals(changed().address,again.address);}
 @Test public void profileDoesNotContainPasswordsOtpOrSession()throws Exception{String json=NasProfile.load(legacy()).routes(changed()).json("Alice").toString();assertFalse(json.contains("secret"));assertFalse(json.contains("123456"));assertFalse(json.contains("_sid"));}
 @Test public void routesDoNotMutateExistingProfile()throws Exception{NasProfile p=NasProfile.load(legacy());String before=p.json("Alice").toString();p.routes(changed());assertEquals(before,p.json("Alice").toString());}
 @Test public void usersAreIsolatedWithinTheSameNas()throws Exception{NasProfile p=NasProfile.load(legacy());assertNotEquals(p.owner("alice"),p.owner("bob"));assertTrue(p.owner("bob").startsWith("nas:"+p.id+"|"));}
 @Test public void separateNewProfilesHaveDistinctOwners()throws Exception{assertNotEquals(NasProfile.load(new TorrentRulesTest.Memory()).owner("alice"),NasProfile.load(new TorrentRulesTest.Memory()).owner("alice"));}
 @Test public void loadUsesSavedProfileInsteadOfMutableLegacyAddress()throws Exception{TorrentRulesTest.Memory m=legacy();NasProfile p=NasProfile.load(m);m.put("nas_profile",p.json("alice").toString());m.put("address","other-address");assertEquals(p.id,NasProfile.load(m).id);assertEquals("fixture-qc|alice",NasProfile.load(m).owner("alice"));}
 @Test public void unrelatedLegacyAccountIsNotInherited()throws Exception{TorrentRulesTest.Memory m=legacy();m.put("libraries_owner","other|bob");assertNotEquals("other|bob",NasProfile.load(m).owner("Alice"));}
 @Test public void invalidProfileIsRejectedWithoutWriting()throws Exception{TorrentRulesTest.Memory m=legacy();m.put("nas_profile","{\"id\":\"broken\",\"owners\":{}}");assertThrows(JSONException.class,()->NasProfile.load(m));assertEquals("{\"id\":\"broken\",\"owners\":{}}",m.get("nas_profile",""));}
 @Test public void oldCacheKeyIsByteIdenticalAfterDdnsEdit()throws Exception{NasProfile p=NasProfile.load(legacy());JSONObject lib=new JSONObject().put("id","movies").put("movie",true).put("paths",new JSONArray().put("/video"));assertEquals(CacheKeys.fileName("fixture-qc|alice",lib),CacheKeys.fileName(p.routes(changed()).owner("Alice"),lib));}
 @Test public void legacyEditsSitesPreparedAndChoicesStayAtSameKeys()throws Exception{TorrentRulesTest.Memory m=legacy();String[] keys={"edits:","torrent_sites:","prepared:"};for(String key:keys)m.put(key+"fixture-qc|alice","fixture-data");m.put("torrent_choice:fixture-qc|alice:list","[0]");String owner=NasProfile.load(m).routes(changed()).owner("Alice");for(String key:keys)assertEquals("fixture-data",m.get(key+owner,""));assertEquals("[0]",m.get("torrent_choice:"+owner+":list",""));}
 static final class RecoveryStore implements NasProfile.Storage {
  final Map<String,String> values=new HashMap<>();public String get(String key,String fallback){return values.getOrDefault(key,fallback);}public void put(String key,String value){values.put(key,value);}public void replaceBrokenProfile(String recovered){values.put("nas_profile_recovery",recovered);values.remove("nas_profile");}
 }
 @Test public void recoveryRemovesCorruptKeyAndKeepsNewIdStableAcrossLoads()throws Exception{RecoveryStore m=new RecoveryStore();m.put("nas_profile","{broken");m.put("address","fixture-qc");m.put("local","http://192.0.2.1:5000");m.put("ddns","https://nas.example.org");m.put("quick","fixture-backup");m.put("user","Alice");m.put("libraries_owner","fixture-qc|alice");m.put("edits:fixture-qc|alice","preserved");assertThrows(JSONException.class,()->NasProfile.load(m));NasProfile p=NasProfile.recover(m);assertFalse(m.values.containsKey("nas_profile"));assertEquals("fixture-qc",p.address);assertEquals("http://192.0.2.1:5000",p.local);assertEquals("https://nas.example.org",p.ddns);assertEquals("fixture-backup",p.quick);assertEquals(0,p.json("").getJSONObject("owners").length());assertNotEquals("fixture-qc|alice",p.owner("Alice"));assertEquals(p.id,NasProfile.load(m).id);assertEquals(p.id,NasProfile.load(m).id);assertEquals("preserved",m.get("edits:fixture-qc|alice",""));}
 @Test public void repeatedExplicitRecoveryCreatesFreshIdentity()throws Exception{RecoveryStore m=new RecoveryStore();NasProfile first=NasProfile.recover(m),second=NasProfile.recover(m);assertNotEquals(first.id,second.id);assertEquals(second.id,NasProfile.load(m).id);}

}
